"""Explain missed hotel-gap windows and compare rotations of the complete route."""
import json,gzip
from datetime import date,datetime
from statistics import median
from zoneinfo import ZoneInfo
from simulate_tacking import ROOT,DATA,Engine
from analyze_start_locations import OUT


def main():
    payloads=[json.loads((OUT/f'{y}-{m}-{d}.json').read_text()) for y in range(2022,2026) for m in ['base','cautious'] for d in ['ccw','cw']]
    runs=[dict(year=p['year'],model=p['model'],direction=p['direction'],**r) for p in payloads for r in p['runs']]
    plan=json.loads((ROOT/'data/phase1/route-plan.json').read_text());name=lambda s:plan['spots'][s]['name']
    models={'base':'Basis','cautious':'Vorsichtig'};directions={'ccw':'Gegen Uhrzeigersinn','cw':'Im Uhrzeigersinn'}
    completed=sum(r['completed'] for r in runs)
    lines=['# Engpässe und Wahl des Startortes','','Stand: 19.10.2026. Dieselben Wind- und Fahrannahmen wie im [Modell mit Aufkreuzen](22-umrundung-mit-aufkreuzen.md): 12–25 kn, maximal fünf Stunden Wasserzeit täglich, 09–17 Uhr, Landpausen und Hotelpflicht. Untersucht werden nun alle **21 erfassten Hotelorte als Start und Ziel** der vollständigen Runde, beide Richtungen, beide Leistungsmodelle und Starttermine 1. August–30. September 2022–2025. Ende jeweils spätestens 31. Oktober.','','## Kurzbefund','','Ein anderer Startort kann den erreichten Fortschritt deutlich erhöhen. Der Start vor einer schwierigen Passage kann deren erstes passendes Windfenster nutzen. Bei einer vollständigen Runde muss allerdings jede Passage einmal gefahren werden; ein Start dahinter verschiebt sie lediglich ans Ende.', '',f'**{completed} vollständige Runden in {len(runs):,} Kombinationen** aus Jahr, Modell, Richtung, Hotelstartort und Starttag. Das ist eine Modellzählung, keine statistische Erfolgswahrscheinlichkeit. Die Wetterverläufe sind rückblickend bekannt und die Starttermine überlappen stark.','','Die entscheidenden Einschränkungen sind lange Strecken zwischen den im Modell zugelassenen Hotelorten, seltene vollständige Fahrfenster und deren zeitliche Reihenfolge. Ein Abschnitt kann grundsätzlich fahrbar sein, sein letztes Fenster aber bereits vorbei sein, wenn die Gruppe dort eintrifft.','','## Konkretes Beispiel: La Cinta → Cala Gonone 2024','','Im Basismodell im Uhrzeigersinn erreicht der weiteste Verlauf ab Poetto **La Cinta am 4. Oktober 2024 um 14:25 Uhr**. Die anschliessende Hotelstrecke nach Cala Gonone ist **67,0 km** lang. Im gesamten Zeitraum August–Oktober gab es dafür nur diese vier geeigneten Tage:', '', '| Datum | Beispiel-Abfahrt | Beispiel-Ankunft | Wasserzeit | Wind am Start¹ |','|---|---|---|---:|---|']
    calendar=json.loads(gzip.decompress((OUT/'2024-base-cw-calendar.json.gz').read_bytes()));i=calendar['nodes'].index('la-cinta');j=calendar['nodes'].index('cala-gonone');engine=Engine('base',2024);zone=ZoneInfo('Europe/Rome');window_examples=[]
    fmt=lambda t:datetime.fromtimestamp(t,zone).strftime('%H:%M')
    for k,day in enumerate(calendar['days']):
        if str(j) not in day[str(i)]:continue
        trip=day[str(i)][str(j)];leg=trip['legs'][0];xy=engine.route(leg['start'],leg['end'])[0][0]['a'];wind=engine.wind(engine.nearest(xy),leg['departure']);when=date(2024,8,1).fromordinal(date(2024,8,1).toordinal()+k).isoformat()
        lines.append(f"| {when} | {fmt(leg['departure'])} | {fmt(trip['legs'][-1]['arrival'])} | {trip['water_hours']:.2f} h | {wind[0]:.1f} kn aus {wind[1]:.0f}° |")
        window_examples.append(dict(date=when,departure=leg['departure'],arrival=trip['legs'][-1]['arrival'],water_hours=trip['water_hours'],start_wind_kn=wind[0],start_wind_from_deg=wind[1]))
    lines+=['','¹ Modellwind am ersten Fahrstück zur Abfahrt, keine Stationsmessung und keine allgemeine Freigabe dieser Windrichtung. Die Prüfung verwendet den Wind während der ganzen Passage. Die westlichen Startwinde in diesen vier Beispielen reichen allein nicht aus, um ein beliebiges anderes Datum als fahrbar einzustufen.','','Das letzte dieser Fenster liegt am Tag der Ankunft in La Cinta. Die gespeicherte geeignete Weiterfahrt beginnt aber bereits um 09:00 Uhr. Für Baja Sardinia → La Cinta sind an diesem Tag schon **4,10 Stunden Wasserzeit** erforderlich, für La Cinta → Cala Gonone in der gezeigten Passage weitere **3,65 Stunden**. Beide passen nicht in einen Fünf-Stunden-Tag. Ab dem nächsten Morgen gibt es bis 31. Oktober kein gültiges Fenster mehr. Der Planer berücksichtigt auch andere Abfahrtszeiten und frühere Hotelalternativen; das Problem ist nicht nur die gezeigte früheste Abfahrt.','','## Weitere seltene Hotelpassagen im Basismodell','','Die Zahlen zählen Tage, an denen die gesamte jeweilige Hotelstrecke mit Pausen, Windgrenzen und Zeitlimit fahrbar ist. Es sind keine Zählungen von Tagen mit irgendeinem Wind über 12 kn. Jede Spalte umfasst 92 Tage August–Oktober.','','| Richtung | Hotelstrecke | Distanz | 2022 | 2023 | 2024 | 2025 |','|---|---|---:|---:|---:|---:|---:|']
    base=[p for p in payloads if p['model']=='base'];gap_keys={(p['direction'],g['start'],g['end']) for p in base for g in p['gaps']}
    entries=[]
    for direction,a,b in gap_keys:
        values=[next(g for g in p['gaps'] if g['start']==a and g['end']==b) for p in base if p['direction']==direction]
        entries.append((sum(len(g['feasible_dates']) for g in values),direction,a,b,values))
    for _,direction,a,b,values in sorted(entries)[:10]:
        lines.append(f"| {directions[direction]} | {name(a)} → {name(b)} | {values[0]['route_km']:.1f} km | "+' | '.join(str(len(g['feasible_dates'])) for g in values)+' |')
    lines+=['','Bei vollständig gegenläufigem Wind beträgt der angenommene Fortschritt im Basismodell rund 6,8–9,8 km/h. Eine 67-km-Hotelstrecke benötigt dann bereits etwa 6,8–9,9 Stunden Wasserzeit – mehr als die erlaubten fünf Stunden. Sie braucht also einen günstigen Kurs zum Wind oder ein Zwischenhotel. Bei passendem Seiten-/Raumwind kann dieselbe Strecke hingegen in einen Tag passen.','','## Was bringt ein anderer Startort?','','Die folgende Tabelle vergleicht ausschliesslich Auguststarts und den maximal erreichten Fortschritt. Die Maxima können aus unterschiedlichen Wetterjahren stammen. Die vollständige Runde bleibt für jeden Startort rund 890,8 km lang.','','| Modell | Richtung | Maximum ab Poetto | Maximum mit anderem Startort | Startort des weitesten Verlaufs | Erste tatsächliche Fahrt |','|---|---|---:|---:|---|---|']
    for model,label in models.items():
        for direction,dlabel in directions.items():
            rows=[r for r in runs if r['model']==model and r['direction']==direction and r['start'][5:7]=='08'];best=max(rows,key=lambda r:r['completed_km']);old=max(r['completed_km'] for r in rows if r['start_hotel']=='poetto')
            lines.append(f"| {label} | {dlabel} | {old:.1f} km | {best['completed_km']:.1f} km | {name(best['start_hotel'])} | {best['first_ride']} |")
    lines+=['','Ein besonders anschaulicher Vergleich im selben Wetterjahr: **2023, Basismodell, im Uhrzeigersinn**. Ab Poetto werden maximal **570,1 km** erreicht; ab **Bosa Marina 823,3 km**. Die erste tatsächliche Fahrt des gezeigten Bosa-Verlaufs erfolgt am **5. August**. Die Gruppe erreicht Torregrande am **30. Oktober**; zur Rückkehr nach Bosa fehlen rund **67,5 km**. Das letzte passende Fenster für diesen Schlussabschnitt liegt wiederum am 30. Oktober. Ein längerer Fortschritt ist daher noch keine geschlossene Runde.','','### Startorte mit hohem Median über die vier Wetterjahre','','Damit nicht nur ein einzelner günstiger Verlauf zählt: je Modell und Richtung die drei Startorte mit dem höchsten Median über alle 124 August-Starttermine. Auch diese Werte beruhen auf überlappenden Startterminen, nicht auf 124 unabhängigen Reisen.','','| Modell | Richtung | Startort | Median Fortschritt | Minimum–Maximum |','|---|---|---|---:|---:|']
    for model,label in models.items():
        for direction,dlabel in directions.items():
            rows=[r for r in runs if r['model']==model and r['direction']==direction and r['start'][5:7]=='08'];ranking=[]
            for hotel in sorted({r['start_hotel'] for r in rows}):
                km=[r['completed_km'] for r in rows if r['start_hotel']==hotel];ranking.append((median(km),max(km),hotel,min(km)))
            for med,mx,hotel,mn in sorted(ranking,reverse=True)[:3]:lines.append(f'| {label} | {dlabel} | {name(hotel)} | {med:.1f} km | {mn:.1f}–{mx:.1f} km |')
    zeros=[(p,g) for p in payloads for g in p['gaps'] if not g['feasible_dates']]
    lines+=['','## Abschnitte ohne ein einziges vollständiges Fenster','','Hier kann eine Rotation unter unveränderten Regeln die Runde im betreffenden Jahr nicht schliessen: Auch ein anderer Start muss die Passage einmal durchfahren.','','| Jahr | Modell | Richtung | Hotelstrecke |','|---|---|---|---|']
    for p,g in zeros:lines.append(f"| {p['year']} | {models[p['model']]} | {directions[p['direction']]} | {name(g['start'])} → {name(g['end'])} |")
    if not zeros:lines.append('| – | – | – | Keine |')
    lines+=['','Umgekehrt garantiert ein vorhandenes Fenster auf jeder Einzelpassage keine komplette Runde. Die Fenster müssen in der richtigen Reihenfolge erreichbar sein.','','## Die Hotelkette ist noch kein vollständiges Unterkunftsnetz','','Die Bedingung „Hotel am Tagesziel“ wurde bisher mit nur 21 recherchierten Hotelorten umgesetzt. Zwischen ihnen liegende Pausenorte durften nicht als Übernachtungsziel zählen. Deshalb wird zum Beispiel La Cinta → Cala Gonone als zusammenhängende 67-km-Tagesstrecke behandelt. Das ist eine Einschränkung unserer Datengrundlage und nicht der Nachweis, dass dazwischen keine Hotels existieren.','','Konkretes Beispiel: Der Betreiber des [Club Hotel Marina Beach](https://www.marinabeach.it/hotel/) nennt **150 m zur Spiaggia Marina di Orosei**. Dieser vorhandene Routenpunkt ist im bisherigen Modell nur ein Pausenort. Als zusätzliches Hotelziel würde er die Strecke La Cinta → Cala Gonone in rund **54,4 km bis Marina di Orosei und 12,6 km bis Cala Gonone** teilen. Der Nutzen für die gesamte Reise ist in der hier berichteten 21-Orte-Startanalyse noch nicht neu simuliert. Hotelöffnungen bleiben wie vereinbart ausser Betracht. Quelle gelesen am 19.10.2026.','','Daraus ergibt sich meine Priorität für die nächste Planungsverbesserung: zuerst die langen Hotelabstände durch weitere belegte strandnahe Übernachtungsorte verkürzen; anschliessend Startort, Richtung und erstes passendes Windfenster gemeinsam optimieren. Die Windgrenzen müssen dafür nicht erneut gelockert werden.','','## Methodik und Grenzen','','- Alle 21 Hotelorte werden als Start **und Ziel derselben vollständigen Runde** betrachtet. Kein Abschnitt darf übersprungen werden.','- 21 Orte × 61 Starttermine × vier Wetterjahre × zwei Richtungen × zwei Leistungsmodelle = 20.496 Kombinationen.','- Tageskalender enthalten alle erreichbaren Hotelziele, mit derselben Wasserzeit-/Landpausenlogik wie zuvor. Die Runde wird zyklisch gedreht, nicht verkürzt.','- Die Auswertung behält alle erreichbaren Übernachtungspositionen bei. Ein Anfangs-Wartetag ist erlaubt; die Spalte „erste tatsächliche Fahrt“ trennt Reisebereitschaft von Abfahrt bei passendem Wind.','- Vergleiche einzelner Tage verwenden historische Kenntnis der gesamten Wetterentwicklung. Die Startempfehlung ist keine Vorhersage für einen künftigen August.','- Die unveränderten Einschränkungen des Modells bleiben: grobes Windraster, hypothetische Leistungswerte, lokale Kreuzschläge statt grossräumiger Ausweichrouten, festes Tageszeitfenster und Ende Oktober als Abschneidegrenze.','','## Quellen, Daten und Reproduktion','','Eigene Auswertung der archivierten [Open-Meteo/ECMWF-IFS-Winddaten](11-wind-api-und-daten.md), der [August-Erweiterung](17-ab-august-180-grad.md), des [Hotelnetzes](13-variable-etappen-wartepausen.md) und des [Aufkreuzmodells](22-umrundung-mit-aufkreuzen.md). Neue Wetterabrufe waren nicht nötig. Der zusätzliche Hotelhinweis ist oben mit Betreiberquelle belegt und wurde nicht stillschweigend in die Simulation aufgenommen.','','```sh','python3 scripts/analyze_start_locations.py','python3 scripts/validate_start_locations.py','python3 scripts/report_start_locations.py',"python3 -m unittest discover -s scripts -p 'test_*.py'",'```','','[Ergebnisverzeichnis](../data/phase2/start-analysis/): je Jahr, Modell und Richtung eine JSON-Auswertung mit allen Startversuchen, vollständigem Fensterkalender je Hotelpassage und beispielhaften Reiseverläufen. Die gzip-Dateien enthalten die wiederverwendbaren täglichen Hotelübergänge. [Validierung](../data/phase2/start-analysis/validation.json) prüft unter anderem die Übereinstimmung aller bisherigen Poetto-Läufe und rekonstruiert die ausgewählten Rundkurse mit Wind-, Küsten- und Zeitprüfung.']
    (OUT/'window-example-2024.json').write_text(json.dumps(window_examples,indent=2)+'\n')
    (ROOT/'docs/23-engpaesse-und-startorte.md').write_text('\n'.join(lines)+'\n')

if __name__=='__main__':main()
